46	/// Redacts known registry/VCS credential env-var values and any URL
47	/// userinfo component from raw `git` subprocess stderr before it is
48	/// embedded in a [`VcsError`] -- a failing `git` invocation can surface an
49	/// authenticated remote URL (e.g. GitHub Actions'
50	/// `REDACTED`) verbatim in its own
51	/// error output, and that text flows into `--format json` and miette
52	/// diagnostic output downstream.
53	fn redact_git_stderr(text: &str) -> String {
54	    callisto_model::redact_known_secrets(text, &callisto_model::known_credential_env_values(std::env::vars()))
55	}
