57	/// Shells `git` subcommands via a [`CommandRunner`] to implement
58	/// [`GitDataSource`]. See the module docs for the consolidation this
59	/// replaces.
60	pub struct ShellGit<'r> {
61	    runner: &'r dyn CommandRunner,
62	    root: PathBuf,
63	}
64	
65	impl<'r> ShellGit<'r> {
66	    pub fn new(runner: &'r dyn CommandRunner, root: impl Into<PathBuf>) -> Self {
67	        ShellGit {
68	            runner,
69	            root: root.into(),
70	        }
71	    }
72	
73	    /// Returns every staged (Git index) change relative to `base`. File
74	    /// contents for additions and modifications are read directly from the
75	    /// worktree with [`std::fs::read`], never through a [`CommandRunner`]
76	    /// (whose captured stdout is a lossy `String`), so CRLF and binary
77	    /// content survive exactly.
78	    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
79	        let output = self.runner.run(
80	            "git",
81	            &["diff", "--cached", "--raw", "-z", "--no-renames", base.as_str()],
82	            &self.root,
83	        )?;
84	        if !output.success() {
85	            return Err(VcsError::Git(format!(
86	                "`git diff --cached --raw` against `{}` failed: {}",
87	                base.as_str(),
88	                redact_git_stderr(&output.stderr)
89	            )));
90	        }
91	
92	        let entries = parse_raw_diff_z(&output.stdout)?;
93	        let mut changes = Vec::with_capacity(entries.len());
94	        for entry in entries {
95	            let kind = staged_change_kind(entry.status);
96	            let contents = match kind {
97	                StagedChangeKindV1::Added | StagedChangeKindV1::Modified => {
98	                    let bytes = std::fs::read(self.root.join(&entry.path)).map_err(|error| {
99	                        VcsError::Git(format!("could not read staged file `{}`: {error}", entry.path))
100	                    })?;
101	                    Some(bytes)
102	                }
103	                _ => None,
104	            };
105	            changes.push(StagedChangeV1 {
106	                path: entry.path,
107	                kind,
108	                new_mode: entry.new_mode,
109	                contents,
110	            });
111	        }
112	        Ok(changes)
113	    }
