115	    /// Returns explicit, fresh Git trust evidence for a durable release.
116	    /// Errors deliberately omit raw stderr and worktree path text.
117	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
118	        let root = self.runner.run("git", &["rev-parse", "--show-toplevel"], &self.root)?;
119	        if !root.success() {
120	            return Err(VcsError::Git(
121	                "could not determine the Git repository root for release trust".to_string(),
122	            ));
123	        }
124	        let canonical_root = canonical_git_root(root.stdout_trimmed())?;
125	
126	        let object_format = self
127	            .runner
128	            .run("git", &["rev-parse", "--show-object-format"], &self.root)?;
129	        if !object_format.success() || object_format.stdout_trimmed() != "sha1" {
130	            return Err(VcsError::Git(
131	                "release trust requires a SHA-1 Git object format".to_string(),
132	            ));
133	        }
134	        let shallow = self
135	            .runner
136	            .run("git", &["rev-parse", "--is-shallow-repository"], &self.root)?;
137	        if !shallow.success() || shallow.stdout_trimmed() != "false" {
138	            return Err(VcsError::Git(
139	                "release trust requires a complete, non-shallow Git repository".to_string(),
140	            ));
141	        }
142	
143	        let head = self
144	            .runner
145	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
146	        if !head.success() {
147	            return Err(VcsError::Git(
148	                "could not resolve a commit for release trust".to_string(),
149	            ));
150	        }
151	        let head = CommitSha::parse(head.stdout_trimmed()).map_err(|error| {
152	            drop(error);
153	            VcsError::Git("Git returned an invalid full HEAD commit for release trust".to_string())
154	        })?;
155	
156	        let symbolic_head = self
157	            .runner
158	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
159	        let head_disposition = match symbolic_head.exit_code {
160	            Some(0) => GitHeadDisposition::Attached,
161	            Some(1) => GitHeadDisposition::Detached,
162	            _ => {
163	                return Err(VcsError::Git(
164	                    "could not determine the symbolic HEAD state for release trust".to_string(),
165	                ))
166	            }
167	        };
168	
169	        let status = self.runner.run(
170	            "git",
171	            &[
172	                "status",
173	                "--porcelain=v1",
174	                "-z",
175	                "--untracked-files=all",
176	                "--ignored=matching",
177	            ],
178	            &self.root,
179	        )?;
180	        if !status.success() {
181	            return Err(VcsError::Git(
182	                "could not inspect the worktree for release trust".to_string(),
183	            ));
184	        }
185	
186	        Ok(GitCommitTrustEvidence::new(
187	            canonical_root,
188	            head,
189	            head_disposition,
190	            parse_release_worktree_status(&status.stdout)?,
191	        ))
192	    }
193	}
